<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x77E9;&#x9635;&#x8BA1;&#x7B97;</text><text class="nav-icon"> </text></view></view><view class="content"><view class="size-row"><view class="size-btn" :class="{active: size===2}" @click="size=2; initMatrices()">2x2</view><view class="size-btn" :class="{active: size===3}" @click="size=3; initMatrices()">3x3</view></view><view class="matrix-section"><text class="section-title">&#x77E9;&#x9635; A</text><view class="matrix-grid" :style="{gridTemplateColumns: 'repeat('+size+',1fr)'}"><input v-for="(v,i) in matrixA" :key="'a'+i" class="matrix-cell" type="number" v-model.number="matrixA[i]" /></view></view><view class="op-row"><view class="op-btn" v-for="op in ops" :key="op" :class="{active: operation===op}" @click="operation=op; calculate()">{{op}}</view></view><view class="matrix-section" v-if="operation!=='det' && operation!=='inv' && operation!=='trans'"><text class="section-title">&#x77E9;&#x9635; B</text><view class="matrix-grid" :style="{gridTemplateColumns: 'repeat('+size+',1fr)'}"><input v-for="(v,i) in matrixB" :key="'b'+i" class="matrix-cell" type="number" v-model.number="matrixB[i]" /></view></view><view class="result-section" v-if="result !== null"><text class="section-title">&#x7ED3;&#x679C;</text><view class="matrix-grid" :style="{gridTemplateColumns: 'repeat('+size+',1fr)'}"><view v-for="(v,i) in result" :key="'r'+i" class="matrix-cell result-cell">{{ typeof v === 'number' ? v.toFixed(2) : v }}</view></view></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const size = ref(2)
const matrixA = ref([1,0,0,1])
const matrixB = ref([1,0,0,1])
const result = ref(null)
const ops = ['+', '-', '×', 'det', 'inv', 'trans']
const operation = ref('+')
function goBack() { uni.navigateBack() }
function initMatrices() { var n = size.value * size.value; matrixA.value = Array(n).fill(0); matrixB.value = Array(n).fill(0); result.value = null }
function calculate() { var n = size.value; var a = matrixA.value; if (operation.value === 'det') { result.value = n === 2 ? [a[0]*a[3]-a[1]*a[2]] : [a[0]*(a[4]*a[8]-a[5]*a[7])-a[1]*(a[3]*a[8]-a[5]*a[6])+a[2]*(a[3]*a[7]-a[4]*a[6])]; return } if (operation.value === 'trans') { var r = []; for (var i = 0; i < n; i++) for (var j = 0; j < n; j++) r.push(a[j*n+i]); result.value = r; return } if (operation.value === 'inv') { if (n === 2) { var det = a[0]*a[3]-a[1]*a[2]; if (det === 0) { result.value = ['singular']; return } result.value = [a[3]/det, -a[1]/det, -a[2]/det, a[0]/det]; return } result.value = ['3x3 inv N/A']; return } var b = matrixB.value; var r2 = []; if (operation.value === '+') for (var k = 0; k < a.length; k++) r2.push(a[k]+b[k]); else if (operation.value === '-') for (var k2 = 0; k2 < a.length; k2++) r2.push(a[k2]-b[k2]); else { for (var ii = 0; ii < n; ii++) for (var jj = 0; jj < n; jj++) { var s = 0; for (var kk = 0; kk < n; kk++) s += a[ii*n+kk]*b[kk*n+jj]; r2.push(s) } } result.value = r2 }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#6366f1,#4f46e5);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.size-row{display:flex;gap:16rpx;margin-bottom:24rpx}.size-btn{flex:1;padding:16rpx;text-align:center;background:#fff;border-radius:12rpx;font-size:28rpx;color:#666}.size-btn.active{background:linear-gradient(135deg,#6366f1,#4f46e5);color:#fff}.matrix-section{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.section-title{font-size:28rpx;color:#333;font-weight:600;display:block;margin-bottom:16rpx}.matrix-grid{display:grid;gap:8rpx}.matrix-cell{width:100%;height:80rpx;background:#f5f7fb;border-radius:8rpx;text-align:center;font-size:28rpx;border:2rpx solid #eee}.result-cell{background:#eef2ff;color:#4f46e5;font-weight:600;display:flex;align-items:center;justify-content:center}.op-row{display:flex;flex-wrap:wrap;gap:12rpx;margin-bottom:24rpx}.op-btn{width:calc(33% - 8rpx);padding:16rpx;text-align:center;background:#fff;border-radius:12rpx;font-size:28rpx;color:#666}.op-btn.active{background:linear-gradient(135deg,#6366f1,#4f46e5);color:#fff}.result-section{background:#fff;border-radius:16rpx;padding:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}</style>